const items = $input.all();

// Pega nome da unidade do contexto do loop
const unidade = $('Loop Unidades').item.json.unidade || 'Desconhecida';

if (items.length === 0) {
  return [{
    json: {
      _status: 'sucesso',
      _unidade: unidade,
      _linhas: 0,
      _msg: `✅ ${unidade} → 0 linhas`
    }
  }];
}

const resultado = items.map(item => {
  const row = item.json;
  const scp = (row.ds_scp || '').toString().trim().toUpperCase();

  // Calcula espessura
  let espessura = 4; // default

  if (scp === '' || scp === null) {
    espessura = 4;
  } else if (/3\+3|03\+03/.test(scp)) {
    espessura = 6;
  } else if (/4\+4|04\+04/.test(scp)) {
    espessura = 8;
  } else if (/04\+06|06\+04/.test(scp)) {
    espessura = 10;
  } else if (/05\+05/.test(scp)) {
    espessura = 10;
  } else if (/8\.38/.test(scp)) {
    espessura = 8;
  } else if (/6\.38/.test(scp)) {
    espessura = 6;
  } else {
    // Tenta extrair número do início (ex: "6MM" → 6, "10MM" → 10)
    const match = scp.match(/^(\d+(\.\d+)?)/);
    if (match) {
      espessura = parseFloat(match[1]);
    }
  }

  const m2 = parseFloat(row.m2) || 0;
  const tonelada = parseFloat((2.5 * espessura * m2 / 1000).toFixed(4));

  return {
    json: {
      ...row,
      espessura: espessura,
      tonelada: tonelada,
      _status: 'sucesso',
      _unidade: unidade,
      _linhas: items.length,
      _msg: `✅ ${unidade} → ${items.length} linhas`
    }
  };
});

const staticData = $getWorkflowStaticData('global');
if (!staticData.resumo) staticData.resumo = [];
staticData.resumo.push(`✅ ${unidade} → ${items.length} linhas`);
staticData.totalLinhas = (staticData.totalLinhas || 0) + items.length;

return resultado;

const items = $input.all();
const seen = new Set();
const result = [];

for (const item of items) {
  const unidade = item.json._unidade;
  if (!seen.has(unidade)) {
    seen.add(unidade);
    result.push({ json: { _status: item.json._status, _unidade: unidade, _linhas: item.json._linhas, _msg: item.json._msg } });
  }
}

return result;

const staticData = $getWorkflowStaticData('global');
const linhas = staticData.resumo || [];
const total = staticData.totalLinhas || 0;

// Limpa pra próxima execução
staticData.resumo = [];
staticData.totalLinhas = 0;

const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Recife' });
const msg = `📊 *Chaparia Tonelada - Carga Diária*\n🕐 ${agora}\n\n${linhas.join('\n')}\n\n📦 Total: ${total} linhas inseridas`;

return [{ json: { mensagem: msg } }];

const unidade = $('Loop Unidades').item.json.unidade || 'Desconhecida';
const erro = $input.first()?.json?.error?.message 
          || $input.first()?.json?.message 
          || 'Erro de conexão';


const staticData = $getWorkflowStaticData('global');
if (!staticData.resumo) staticData.resumo = [];
staticData.resumo.push(`❌ ${unidade} → ERRO: ${erro}`);

return [{
  json: {
    _status: 'erro',
    _unidade: unidade,
    _linhas: 0,
    _msg: `❌ ${unidade} → ERRO: ${erro}`
  }
}];
